  /// tick (one chain — [scheduledTickPending] guards it).
  (Model, Cmd?) _handleWaitingStatus(WaitingStatusMsg msg) {
    final next = copyWith(
      waitingJobs: msg.jobs,
      waitingTimers: msg.timers,
