  /// while #88's anti-theft tagging protects only LIVE foreign owners.
  /// Pending record files stay put either way — they are the source of
  /// truth; a later [start] (host restart, session switch) re-arms and
  /// delivers them.
  void dispose() {
    _disposed = true;
